// TinyMCE 8 Course Link Plugin
//
// Opens course/courselinkdialog.php in a TinyMCE URL dialog, letting the user
// pick a course item or folder. Inserts a stable, tagged link
// (class="courselink" data-courselink-*) so includes/copyiteminc.php can
// find and remap these links during a course copy, and so export code
// (exportitems2.php, ccexport-generate.php, bbexport-generate.php) can strip
// them, since they're meaningless outside the source install.
//
// Follows the same openUrl request/response convention already used by the
// mathquill plugin (tinymce8/plugins/mathquill/plugin.min.js): a custom
// footer button's onAction asks the iframe (via dialogApi.sendMessage) for
// its current selection; the iframe replies via TinyMCE's built-in
// mceAction:'customAction' envelope, which onMessage below unwraps to
// actually insert the link and close the dialog.
(function () {
  'use strict';

  tinymce.PluginManager.add('courselink', function (editor) {

    editor.ui.registry.addIcon('courselink', '<svg width="24" height="24" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path d="M3 5.5C3 4.67 3.67 4 4.5 4H10v2H5v14h14v-5h2v5.5c0 .83-.67 1.5-1.5 1.5h-15A1.5 1.5 0 0 1 3 20.5v-15Z"/><path d="M13 4h7v7h-2V7.41l-8.29 8.3-1.42-1.42 8.3-8.29H13V4Z"/></svg>');

    function escapeHtml(s) {
      return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
        .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    }

    // Finds the enclosing courselink <a>, if the cursor/selection is
    // currently inside one -- lets us pre-select it in the picker and
    // replace it in place instead of nesting a new link inside it.
    function getExistingLink() {
      return editor.dom.getParent(editor.selection.getNode(), function (n) {
        return n.nodeName === 'A' && n.classList && n.classList.contains('courselink');
      });
    }

    function openCourseLinkDialog() {
      const existingLink = getExistingLink();

      let dialogUrl = imasroot + '/course/courselinkdialog.php?cid=' + cid;
      if (existingLink) {
        // only meaningful to pre-select if the link points within this same
        // course -- the picker's tree only ever lists this course's items
        const linkCid = existingLink.getAttribute('data-courselink-cid');
        const linkType = existingLink.getAttribute('data-courselink-type');
        const linkId = existingLink.getAttribute('data-courselink-id');
        if (linkCid && linkType && linkId && String(linkCid) === String(cid)) {
          dialogUrl += '&selected=' + encodeURIComponent(linkType + linkId);
        }
        if (existingLink.getAttribute('target') === '_blank') {
          dialogUrl += '&newwindow=1';
        }
      }

      editor.windowManager.openUrl({
        title: 'Insert Course Link',
        url: dialogUrl,
        width: 480,
        height: 550,
        buttons: [
          { type: 'cancel', text: 'Cancel' },
          { type: 'custom', name: 'insert', text: 'Insert Link', primary: true }
        ],
        onAction: function (api, details) {
          if (details.name === 'insert') {
            // ask the iframe what's currently selected in its tree
            api.sendMessage({ type: 'courselink-getselection' });
          }
        },
        onMessage: function (api, data) {
          if (data.mceAction === 'customAction' && data.data && data.data.href) {
            const d = data.data;
            const newWindow = d.target === '_blank';
            if (existingLink) {
              // replace the existing link's target in place, rather than
              // inserting a new nested link
              editor.dom.setAttribs(existingLink, {
                href: d.href,
                'data-courselink-type': d.type,
                'data-courselink-cid': d.cid,
                'data-courselink-id': d.id,
                target: newWindow ? '_blank' : null,
                rel: newWindow ? 'noopener' : null
              });
              existingLink.textContent = d.text;
              editor.selection.select(existingLink);
              editor.selection.collapse(false);
              editor.nodeChanged();
            } else {
              const html = '<a href="' + escapeHtml(d.href) + '" class="courselink" ' +
                'data-courselink-type="' + escapeHtml(d.type) + '" ' +
                'data-courselink-cid="' + escapeHtml(d.cid) + '" ' +
                'data-courselink-id="' + escapeHtml(d.id) + '"' +
                (newWindow ? ' target="_blank" rel="noopener"' : '') +
                '>' + escapeHtml(d.text) + '</a>';
              editor.insertContent(html);
            }
            api.close();
          }
        }
      });
    }

    editor.ui.registry.addToggleButton('courselink', {
      icon: 'courselink',
      tooltip: 'Insert Course Link',
      onAction: openCourseLinkDialog,
      onSetup: function (api) {
        function updateState() {
          const node = editor.selection.getNode();
          api.setActive(node.nodeName === 'A' && node.classList.contains('courselink'));
        }
        editor.on('NodeChange', updateState);
        return function () {
          editor.off('NodeChange', updateState);
        };
      }
    });

    editor.ui.registry.addMenuItem('courselink', {
      icon: 'courselink',
      text: 'Course Link',
      onAction: openCourseLinkDialog
    });

    editor.addCommand('mceInsertCourseLink', openCourseLinkDialog);

    return {
      getMetadata: function () {
        return { name: 'Course Link Plugin' };
      }
    };
  });
})();
